class Solution {
public:
    int numOfSubarrays(vector<int>& arr, int k, int threshold) {
        long long target = (long long)k * threshold;
        long long curr = 0;
        for (int i = 0; i < k; i++) curr += arr[i];
        int count = (curr >= target) ? 1 : 0;
        for (int i = k; i < (int)arr.size(); i++) {
            curr += arr[i] - arr[i - k];
            if (curr >= target) count++;
        }
        return count;
    }
};

